def build():
    out=[]
    for line in rows.strip().splitlines():
        term,prompt,answer,*rest=line.split('|');assert len(rest)==4
        out.append({'draftID':f'easy-13-{len(out)+1:03d}','categoryID':'13','difficulty':'easy','prompt':prompt,'answers':[answer,*rest[:3]],'correctIndex':0,'rationale':rest[3],
                    'sourceURL':term if term.startswith('https://') else 'https://dictionary.cambridge.org/dictionary/english/'+term,'reviewStatus':'draft_awaiting_author_final_check'})
    return out
if __name__=='__main__':
    draft=build();(HERE/'draft.json').write_text(json.dumps(draft,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
    print(f'{len(draft)} candidates; editorial approval not performed by this script.')
